// Получаем полный ответ GPT
const gptResponse = $('GPT-4o: Оценка звонка').item.json.message.content;

// Разделяем ответ на отчёт для Telegram и JSON для таблицы
let telegramReport = '';
let jsonData = {};

// Извлекаем отчёт для Telegram
const telegramMatch = gptResponse.match(/---РАЗДЕЛ 1: ОТЧЁТ ДЛЯ TELEGRAM---\n([\s\S]*?)\n---РАЗДЕЛ 2: JSON ДЛЯ ТАБЛИЦЫ---/);
if (telegramMatch) {
  telegramReport = telegramMatch[1].trim();
} else {
  // Fallback: весь ответ идёт как отчёт
  telegramReport = gptResponse;
}

// Извлекаем JSON для таблицы
const jsonMatch = gptResponse.match(/---РАЗДЕЛ 2: JSON ДЛЯ ТАБЛИЦЫ---\n([\s\S]*?)$/);
if (jsonMatch) {
  try {
    const rawJson = jsonMatch[1].trim();
    // Ищем JSON-объект в тексте
    const jsonStr = rawJson.match(/\{[\s\S]*\}/)[0];
    jsonData = JSON.parse(jsonStr);
  } catch (e) {
    jsonData = {
      manager: 'Ошибка парсинга',
      lot_type: '',
      task: 'Ошибка разбора JSON: ' + e.message,
      needs_score: 0,
      presentation_score: 0,
      objections_score: 0,
      transfer_score: 0,
      lots_score: 0,
      mandatory_questions: '',
      service_score: 0,
      average_score: 0
    };
  }
}

// Формируем дату и время
const now = new Date();
const date = now.toLocaleDateString('ru-RU');
const time = now.toLocaleTimeString('ru-RU', { hour: '2-digit', minute: '2-digit' });

// Номер — chat ID отправителя
const chatId = $('Telegram Trigger').item.json.message.chat.id;
const senderName = $('Telegram Trigger').item.json.message.from.first_name || '';
const senderLast = $('Telegram Trigger').item.json.message.from.last_name || '';
const sender = (senderName + ' ' + senderLast).trim();

return {
  json: {
    telegramReport: telegramReport,
    date: date,
    manager: jsonData.manager || 'Не определён',
    number: String(chatId),
    time: time,
    lot_type: jsonData.lot_type || 'Не определён',
    task: jsonData.task || '',
    needs_score: jsonData.needs_score || 0,
    presentation_score: jsonData.presentation_score || 0,
    objections_score: jsonData.objections_score || 0,
    transfer_score: jsonData.transfer_score || 0,
    lots_score: jsonData.lots_score || 0,
    mandatory_questions: jsonData.mandatory_questions || '',
    service_score: jsonData.service_score || 0,
    average_score: jsonData.average_score || 0,
    sender: sender
  }
};
